  7	/**
  8	 * Executor of the method `estimate-exit-cost-by-series` (v7, after the fifth independent review).
  9	 * For each series an alternative wants to retire on a date: which mechanisms its indenture offers on
 10	 * that date, each with its own formula, scope and quote day, and what each costs with what the base
 11	 * holds. The base of any price is the nominal at the exit date (updated where indexed, with the
 12	 * derivation the source allows), the remuneration accrued to that date and the charges the indenture
 13	 * states, each dated at the exit and anchored; a 31/05 balance is not a nominal at 04/09, and a
 14	 * missing component is insufficient evidence, never zero. Mechanisms are never merged: the DI
 15	 * premium is [(1 + p)^(DU/252) - 1] over the amount retired, truncated at eight decimals; an
 16	 * extraordinary amortization retires a fraction the indenture caps and never competes as a full
 17	 * exit; a make-whole redemption discounts the remaining flows at the quote of the contractual day
 18	 * (the prior or the second prior business day, as the series says, and that distance is checked
 19	 * against the calendar), adds the charges the indenture adds, and applies the floor the series says
 20	 * (the updated value, or none); the duration that selects the reference security is discounted at
 21	 * the series' own remuneration; a negotiated offer is open since issuance with a premium to be set;
 22	 * an acquisition depends on the seller and may be partial. Every anchor names a document of the
 23	 * base's registry and every mechanism cites the series' indenture with its clause; a series without
 24	 * an indenture is not priced. Business days are the weekdays less the holidays the calendar lists,
 25	 * for the DI premium as for the quote distance. A negotiated offer retires what adheres, all or
 26	 * part. The reference security of a make-whole must be the nearest in duration among the
 27	 * candidates the base lists (by business days for an NTN-B, by calendar days for a Pre x DI vertex),
 28	 * or the route is insufficient evidence; a tie between candidates is recorded. The DI premium is
 29	 * computed per debenture on the unit price and truncated, then multiplied by the quantity, when
 30	 * the base gives the quantity; otherwise on the aggregate, declared as an approximation. Discount
 31	 * factors of a make-whole are rounded at nine decimals, as the indentures write. A negotiated offer
 32	 * prices what adhered: with the premium known and the adhesion unknown, nothing is retired yet.
 33	 * Mechanisms the indenture offers and the input does not represent are named as gaps.
 34	 */
 35	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 36	const nonEmpty = z.string().trim().min(1);
 37	/** A calendar date that exists: the regex alone would let 2026-99-99 through. */
 38	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => { const [year, month, day] = value.split("-").map(Number) as [number, number, number]; const date = new Date(Date.UTC(year, month - 1, day)); return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day; }, {message: "not a calendar date"});
 39	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 40	const anchorSchema = z.object({document: nonEmpty, clause: nonEmpty.optional(), page: z.number().int().positive().optional(), note: nonEmpty.optional()}).strict();
 41	type Anchor = z.infer<typeof anchorSchema>;
 42	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 43	
 44	/** A dated amount with its anchor; the base of every price is built from these, never from a default. */
 45	const datedAmountSchema = z.object({value: nonNegative, asOf: isoDate, anchor: anchorSchema}).strict();
 46	const quoteSchema = z.object({
 47	  rate: nonNegative,
 48	  quoteDate: isoDate,
 49	  /** Business days between the quote date and the exit date: the weekdays between them less the holidays the calendar lists. */
 50	  businessDaysBeforeExit: z.number().int().positive(),
 51	  /** Holidays between the quote date and the exit date, from the calendar the base cites (zero must be stated too). */
 52	  holidaysBetween: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(),
 53	  security: nonEmpty,
 54	  /** The reference security's own duration (business days for an NTN-B, calendar days for a Pre x DI vertex), and the candidates the source lists with theirs: the chosen security must be the nearest to the series' duration on the same count. */
 55	  securityDurationBusinessDays: z.number().int().positive().nullable().default(null),
 56	  securityCalendarDays: z.number().int().positive().nullable().default(null),
 57	  candidates: z.array(z.object({security: nonEmpty, durationBusinessDays: z.number().int().positive().nullable().default(null), calendarDays: z.number().int().positive().nullable().default(null)}).strict()).min(1),
 58	  anchor: anchorSchema,
 59	}).strict();
 60	/** Business days to maturity: the weekdays between the exit and the maturity less the holidays the calendar lists (zero must be stated too). */
 61	const businessDaysSchema = z.object({count: z.number().int().nonnegative(), maturity: isoDate, holidays: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(), anchor: anchorSchema}).strict();
 62	const referenceRateSchema = z.enum(["NTN-B (ANBIMA indicative, nearest duration)", "B3 Pre x DI curve (nearest vertex to remaining duration)"]);
 63	const makeWholeFields = {
 64	  availableFrom: isoDate,
 65	  referenceRate: referenceRateSchema,
 66	  /** The floor the series writes: the updated value (max of A and B) or none (present value only). */
 67	  floor: z.enum(["max_with_base", "present_value_only"]),
 68	  /** The contractual quote day the series writes. */
 69	  quoteDay: z.enum(["prior_business_day", "second_prior_business_day"]),
 70	  /** The quote of that day, when the base holds it. */
 71	  quote: quoteSchema.nullable(),
 72	  anchor: anchorSchema,
 73	};
