 75	export const exitMechanismSchema = z.discriminatedUnion("mechanism", [
 76	  z.object({
 77	    mechanism: z.literal("extraordinary_amortization_di"),
 78	    /** Premium per year as a decimal (0.004 for 0,40%), applied as [(1 + p)^(DU/252) - 1] over the amount retired. */
 79	    premiumPerYear: nonNegative,
 80	    availableFrom: isoDate,
 81	    /** The share of the nominal the indenture lets an amortization retire (0.98 for 98%), and the share this alternative retires. */
 82	    maxFraction: nonNegative,
 83	    fraction: nonNegative,
 84	    businessDays: businessDaysSchema,
 85	    anchor: anchorSchema,
 86	  }).strict(),
 87	  z.object({mechanism: z.literal("total_redemption_di"), premiumPerYear: nonNegative, availableFrom: isoDate, businessDays: businessDaysSchema, anchor: anchorSchema}).strict(),
 88	  z.object({mechanism: z.literal("extraordinary_amortization_ipca"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
 89	  z.object({mechanism: z.literal("total_redemption_ipca"), ...makeWholeFields}).strict(),
 90	  z.object({mechanism: z.literal("extraordinary_amortization_pre"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
 91	  z.object({mechanism: z.literal("total_redemption_pre"), ...makeWholeFields}).strict(),
 92	  z.object({
 93	    mechanism: z.literal("negotiated_offer"),
 94	    /** Open since issuance in the 13th, 14th and 15th; the premium is what the notice states (a rate, an amount per debenture or a total) and the holders decide; what adheres is retired, all or part. */
 95	    availableFrom: isoDate,
 96	    premium: z.discriminatedUnion("kind", [
 97	      z.object({kind: z.literal("rate"), rate: nonNegative, anchor: anchorSchema}).strict(),
 98	      z.object({kind: z.literal("amount_per_unit"), value: nonNegative, anchor: anchorSchema}).strict(),
 99	      z.object({kind: z.literal("total"), value: nonNegative, anchor: anchorSchema}).strict(),
100	    ]).nullable(),
101	    requiresFullAdherence: z.boolean(),
102	    /** The share of the series that adhered, when a notice and its result are in the base; null before that; never above one. */
103	    adhesion: z.object({fraction: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
104	    anchor: anchorSchema,
105	  }).strict(),
106	  z.object({mechanism: z.literal("acquisition"), availableFrom: isoDate.nullable(), anchor: anchorSchema}).strict(),
107	]);
108	const MAKE_WHOLE = new Set(["extraordinary_amortization_ipca", "total_redemption_ipca", "extraordinary_amortization_pre", "total_redemption_pre"]);
109	const PARTIAL = new Set(["extraordinary_amortization_di", "extraordinary_amortization_ipca", "extraordinary_amortization_pre"]);
110	
111	export const exitCostInputSchema = z.object({
112	  exitDate: isoDate,
113	  unit: unitSchema,
114	  /** The documents of the base; every anchor must name one of them, and a mechanism must cite an indenture. */
115	  documents: z.array(z.object({name: nonEmpty, kind: z.enum(["indenture", "itr", "ledger", "quote", "calendar", "notice", "market_data", "other"])}).strict()).min(1),
116	  series: z.array(z.object({
117	    id: nonEmpty,
118	    label: nonEmpty,
119	    /** The indenture that governs the series; without one in the base the series is not priced. */
120	    indenture: z.object({document: nonEmpty, clause: nonEmpty.optional()}).strict().nullable(),
121	    /** Nominal at the exit date (updated where indexed), with the derivation the source allows; null when the base does not hold it. */
122	    nominalAtExit: z.object({value: nonNegative, asOf: isoDate, derivation: z.enum(["unit_value_x_quantity_updated", "unit_value_x_quantity", "ledger_balance_at_exit_date", "trustee_report_at_exit_date"]), anchor: anchorSchema}).strict().nullable(),
123	    /** Remuneration accrued to the exit date; null when the base does not hold it (never zero by default). */
124	    accruedAtExit: datedAmountSchema.nullable(),
125	    /** Charges due at the exit date as the indenture states them, an explicit zero included; null when the base is silent. */
126	    chargesAtExit: datedAmountSchema.nullable(),
127	    /** Remaining flows after the exit date for the make-whole prices, each with its business and calendar days from the exit date; null when the base has no schedule. */
128	    remainingFlows: z.array(z.object({id: nonEmpty, date: isoDate, amount: nonNegative, businessDaysFromExit: z.number().int().positive(), calendarDaysFromExit: z.number().int().positive(), anchor: anchorSchema}).strict()).nullable(),
129	    /** Debentures outstanding, so the DI premium is computed per unit and truncated as the indenture writes; null when the base does not state it. */
130	    quantity: z.number().int().positive().nullable(),
131	    /** The mechanisms the indenture offers this series, as the base lists them; any of them absent from `mechanisms` is a gap the executor names. */
132	    indentureMechanisms: z.array(nonEmpty).default([]),
133	    /** The series' own remuneration as an annual rate (the real spread for an IPCA series, the fixed rate for a pre series), which the indenture uses to discount the duration that selects the reference security. */
134	    remunerationRate: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
135	    mechanisms: z.array(exitMechanismSchema),
136	    anchor: anchorSchema,
137	  }).strict()),
138	}).strict().superRefine((input, context) => {
139	  const documents = new Map(input.documents.map((document) => [document.name, document.kind]));
140	  const names = new Set<string>();
141	  input.documents.forEach((document, index) => { if (names.has(document.name)) context.addIssue({code: "custom", path: ["documents", index], message: `duplicate document ${document.name}`}); names.add(document.name); });
142	  const checkAnchor = (anchor: Anchor, path: (string | number)[]) => { if (!documents.has(anchor.document)) context.addIssue({code: "custom", path, message: `anchor names ${anchor.document}, which is not a document of the base`}); };
143	  const ids = new Set<string>();
144	  input.series.forEach((series, index) => {
145	    if (ids.has(series.id)) context.addIssue({code: "custom", path: ["series", index], message: `duplicate series ${series.id}`});
146	    ids.add(series.id);
147	    checkAnchor(series.anchor, ["series", index, "anchor"]);
148	    if (series.indenture && documents.get(series.indenture.document) !== "indenture") context.addIssue({code: "custom", path: ["series", index, "indenture"], message: `${series.id}: ${series.indenture.document} is not registered as an indenture`});
149	    for (const [name, amount] of [["nominalAtExit", series.nominalAtExit], ["accruedAtExit", series.accruedAtExit], ["chargesAtExit", series.chargesAtExit]] as const) {
150	      if (!amount) continue;
151	      checkAnchor(amount.anchor, ["series", index, name, "anchor"]);
152	      if (amount.asOf !== input.exitDate) context.addIssue({code: "custom", path: ["series", index, name], message: `${series.id}: ${name} dated ${amount.asOf} is not the base at the exit date ${input.exitDate}`});
153	    }
154	    const flowIds = new Set<string>();
155	    (series.remainingFlows ?? []).forEach((flow, position) => {
156	      checkAnchor(flow.anchor, ["series", index, "remainingFlows", position, "anchor"]);
157	      if (flowIds.has(flow.id)) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: duplicate flow ${flow.id}`});
