220	/** Weekdays strictly after `from` up to and including `to`, the ceiling of any business-day count. */
221	export function weekdaysBetween(from: string, to: string): number {
222	  const start = new Date(`${from}T00:00:00Z`);
223	  const end = new Date(`${to}T00:00:00Z`);
224	  let count = 0;
225	  for (let day = new Date(start.getTime() + 86_400_000); day <= end; day = new Date(day.getTime() + 86_400_000)) {
226	    const weekday = day.getUTCDay();
227	    if (weekday !== 0 && weekday !== 6) count += 1;
228	  }
229	  return count;
230	}
