241	/** A single traced calculation with its formula and operands, for functions that return more than one figure. */
242	export type CalculationTrace = {id: string; formula: string; operands: Record<string, string>; result: string};
243	
244	/**
245	 * Present value of dated flows discounted at an annual effective rate over business days of a
246	 * 252-day year: PV = sum(amount / (1 + rate)^(businessDays / 252)). Used by the exit-cost method
247	 * for the make-whole prices the indentures define at a quoted rate.
248	 */
249	export function presentValueByBusinessDays(flows: Array<{id: string; amount: string; businessDays: number}>, annualRate: string, options: {factorDecimals?: number; presentValueDecimals?: number} = {}): {value: string; discounted: Array<{id: string; amount: string; businessDays: number; factor: string; presentValue: string}>; trace: CalculationTrace} {
250	  if (!/^\d+(\.\d+)?$/.test(annualRate)) throw new Error("annualRate must be a non-negative decimal string");
251	  const rate = new Decimal(annualRate);
252	  let total = new Decimal(0);
253	  const discounted = flows.map((flow) => {
254	    if (!Number.isInteger(flow.businessDays) || flow.businessDays < 0) throw new Error(`flow ${flow.id}: businessDays must be a non-negative integer`);
255	    // An indenture may round the discount factor of each flow (FVPk at nine decimals) before dividing; the option keeps that layer.
256	    const rawFactor = rate.plus(1).pow(new Decimal(flow.businessDays).div(252));
257	    const factor = options.factorDecimals === undefined ? rawFactor : rawFactor.toDecimalPlaces(options.factorDecimals, Decimal.ROUND_HALF_UP);
258	    const presentValue = options.presentValueDecimals === undefined ? new Decimal(flow.amount).div(factor) : new Decimal(flow.amount).div(factor).toDecimalPlaces(options.presentValueDecimals, Decimal.ROUND_HALF_UP);
259	    total = total.plus(presentValue);
260	    return {id: flow.id, amount: new Decimal(flow.amount).toFixed(), businessDays: flow.businessDays, factor: factor.toDecimalPlaces(12).toFixed(), presentValue: presentValue.toDecimalPlaces(8).toFixed()};
261	  });
262	  const value = total.toDecimalPlaces(8).toFixed();
263	  return {value, discounted, trace: {id: "financial.present_value_by_business_days", formula: "sum(amount / (1 + annualRate)^(businessDays/252))", operands: {annualRate, flows: String(flows.length), factorDecimals: options.factorDecimals === undefined ? "none" : String(options.factorDecimals), presentValueDecimals: options.presentValueDecimals === undefined ? "none" : String(options.presentValueDecimals)}, result: value}};
264	}
265	
266	/** Macaulay duration in business days of dated flows at an annual effective rate: sum(DU * PV) / sum(PV). */
267	export function macaulayDurationBusinessDays(flows: Array<{id: string; amount: string; businessDays: number}>, annualRate: string): {value: string; trace: CalculationTrace} {
268	  const present = presentValueByBusinessDays(flows, annualRate);
269	  const total = new Decimal(present.value);
270	  if (total.isZero()) throw new Error("duration is undefined for flows with zero present value");
271	  const weighted = present.discounted.reduce((sum, flow) => sum.plus(new Decimal(flow.presentValue).times(flow.businessDays)), new Decimal(0));
272	  const value = weighted.div(total).toDecimalPlaces(8).toFixed();
273	  return {value, trace: {id: "financial.macaulay_duration_business_days", formula: "sum(businessDays * presentValue) / sum(presentValue)", operands: {annualRate, flows: String(flows.length), presentValue: present.value}, result: value}};
274	}
