276	/**
277	 * Accrual factor over business days of a 252-day year kept at the precision an indenture writes:
278	 * (1 + annualRate)^(businessDays / 252) - 1, or, with a percentage of the index, the daily rate
279	 * times the percentage compounded over the days. `decimals` and `mode` are the layer the indenture
280	 * states (a DI factor at eight decimals rounded, a daily accumulation at sixteen truncated).
281	 */
282	export function accrualFactorAtPrecision(input: {annualRate: DecimalInput; businessDays: number; percentOfIndex?: DecimalInput; decimals: number; mode: "round" | "truncate"}): {value: string; trace: CalculationTrace} {
283	  if (!Number.isInteger(input.businessDays) || input.businessDays < 0) throw new Error("businessDays must be a non-negative integer");
284	  if (!Number.isInteger(input.decimals) || input.decimals < 0 || input.decimals > 20) throw new Error("decimals must be an integer between 0 and 20");
285	  const rounding = input.mode === "truncate" ? Decimal.ROUND_DOWN : Decimal.ROUND_HALF_UP;
286	  let factor: Decimal;
287	  if (input.percentOfIndex === undefined) {
288	    factor = new Decimal(input.annualRate).plus(1).pow(new Decimal(input.businessDays).div(252)).minus(1);
289	  } else {
290	    const daily = new Decimal(input.annualRate).plus(1).pow(new Decimal(1).div(252)).minus(1).times(input.percentOfIndex);
291	    factor = daily.plus(1).pow(input.businessDays).minus(1);
292	  }
