const Decimal=require('decimal.js'); Decimal.set({precision:40});
const D=x=>new Decimal(x);
function dur(a1,a2,d1,d2,rate,roundedFactors,pvRound8,totalRound8){
 const rows=[[D(a1),d1],[D(a2),d2]].map(([a,d])=>{let f=D(1).plus(rate).pow(D(d).div(252)); if(roundedFactors) f=f.toDecimalPlaces(9,Decimal.ROUND_HALF_UP); let pv=a.div(f); const out=pv.toDecimalPlaces(8,Decimal.ROUND_HALF_UP); return {pv,out,d}});
 let total=rows.reduce((s,x)=>s.plus(pvRound8?x.out:x.pv),D(0)); if(totalRound8) total=total.toDecimalPlaces(8,Decimal.ROUND_HALF_UP);
 let num=rows.reduce((s,x)=>s.plus((pvRound8?x.out:x.pv).times(x.d)),D(0));
 return num.div(total);
}
const d1=125,d2=252,rate='0.06',target=D('200.5');
// solve ratio a2/a1 for exact rounded-factor source target
let f1=D(1).plus(rate).pow(D(d1).div(252)).toDecimalPlaces(9); let f2=D(1).plus(rate).pow(D(d2).div(252)).toDecimalPlaces(9);
// target=(d1*x+d2*y)/(x+y), y/x=(target-d1)/(d2-target); a2/a1=y*f2/(x*f1)
let ratio=target.minus(d1).div(D(d2).minus(target)).times(f2).div(f1);
for(const eps of ['-0.00000001','-0.000000001','0','0.000000001','0.00000001']){
 let a2=ratio.plus(eps);
 let src=dur('1',a2,d1,d2,rate,true,false,false);
 let exe=dur('1',a2,d1,d2,rate,false,true,true);
 console.log({a2:a2.toFixed(12),src:src.toFixed(12),exe:exe.toFixed(12),sideSrc:src.cmp(target),sideExe:exe.cmp(target)});
}
